body.script:
function calculateTDEE(){
    let gender = document.getElementById('gender').value;
    let age = parseFloat(document.getElementById('age').value);
    let weight = parseFloat(document.getElementById('weight').value);
    let height = parseFloat(document.getElementById('height').value);
    let activity = parseFloat(document.getElementById('activity').value);

    if(!age || !weight || !height){
        alert('Please fill in age, weight, and height before calculating.');
        return;
    }

    let bmr;
    if(gender === 'male') {
        bmr = 10 * weight + 6.25 * height - 5 * age + 5;
    } else {
        bmr = 10 * weight + 6.25 * height - 5 * age - 161;
    }

    let tdee = Math.round(bmr * activity);
    let lose = Math.round(tdee * 0.85);
    let gain = Math.round(tdee * 1.10);

    document.getElementById('result').style.display = 'block';
    document.getElementById('tdeeResult').innerText = tdee + ' kcal';
    document.getElementById('bmrResult').innerText = Math.round(bmr);
    document.getElementById('loseResult').innerText = lose;
    document.getElementById('maint2').innerText = tdee;
    document.getElementById('gainResult').innerText = gain;
    document.getElementById('result').scrollIntoView({behavior:'smooth'});
}
